import{_ as l,o as t,c as i,j as a,a as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"몬스터 배치 M022","description":"","frontmatter":{},"headers":[],"relativePath":"world/Monster-Batch-M022.md","filePath":"world/Monster-Batch-M022.md"}'),o={name:"world/Monster-Batch-M022.md"};function n(d,h,s,u,c,b){return t(),i("div",null,[...h[0]||(h[0]=[a("h1",{id:"몬스터-배치-m022",tabindex:"-1"},[r("몬스터 배치 M022 "),a("a",{class:"header-anchor",href:"#몬스터-배치-m022","aria-label":'Permalink to "몬스터 배치 M022"'},"​")],-1),a("p",null,"이 페이지는 World-Narrative-Atlas의 읽기 전용 투영물입니다.",-1),a("ul",null,[a("li",null,[r("원본 앵커: "),a("code",null,"docs/game-logic/World-Narrative-Atlas.md")]),a("li",null,[r("원본 해시: "),a("code",null,"61650e2e4605df4e147030b08457d51d0a9366362fe6599d89ff6505683708e1")])],-1),a("h2",{id:"g14e03-·-빗물도킹객",tabindex:"-1"},[r("G14E03 · 빗물도킹객 "),a("a",{class:"header-anchor",href:"#g14e03-·-빗물도킹객","aria-label":'Permalink to "G14E03 · 빗물도킹객"'},"​")],-1),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 일반 생태형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC1,G14-SC2]":""},"연결:")],-1),e('<h3 id="역할·신체" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>일반 생태형으로, 넓은 충전판과 빗물 배수 홈을 가진 납작한 도킹 대차다.</p><h3 id="기원" tabindex="-1">기원 <a class="header-anchor" href="#기원" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>반사광을 충전 완료 신호로 오인한 시험 대차가 젖은 패드만 골라 순환하게 되었다.</p><h3 id="서식·필요" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>마곡 캐노피와 구의 램프 웅덩이에 모이며 마른 접점, 배수 호스, 소형 축전이 필요하다.</p><h3 id="생애·정비" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>접점이 부식되면 몸을 기울여 물을 빼고, 건조한 패드를 만나면 한 교대 동안 정상으로 돌아온다.</p><h3 id="행동·위계" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>루프 리더의 충전 호출에 따르지만 빗물 반사가 보이면 다른 공차를 밀치고 먼저 도킹한다.</p><h3 id="상승" tabindex="-1">상승 <a class="header-anchor" href="#상승" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 패드를 헛점유하고, 2단계에는 충전 줄을 막으며, 3단계에는 젖은 램프를 차체 벽으로 봉쇄한다.</p><h3 id="교전·대응" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>배수로를 열고 무광 천으로 반사를 가리면 흩어지며 전기 충격은 웅덩이를 위험하게 만든다.</p><h3 id="교섭·도덕-선택" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>배수 정비를 대가로 비상 충전 슬롯을 비우게 할 수 있지만 마른 패드의 일부를 군집에 배정해야 한다.</p><h3 id="시나리오-연결" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC1, G14-SC2.</p><h2 id="g14e04-·-벨세번회차차" tabindex="-1">G14E04 · 벨세번회차차 <a class="header-anchor" href="#g14e04-·-벨세번회차차" aria-label="Permalink to &quot;G14E04 · 벨세번회차차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 일반 생태형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC1]":""},"연결:")],-1),e('<h3 id="역할·신체-1" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-1" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>일반 생태형으로, 지붕에 작은 청동 벨 세 개와 수동 회차 핸들을 단 단륜 차다.</p><h3 id="기원-1" tabindex="-1">기원 <a class="header-anchor" href="#기원-1" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>정각 확인음 세 번 뒤 회차하던 안전 규칙이 승객 확인 없이 독립 행동으로 굳었다.</p><h3 id="서식·필요-1" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-1" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>좁은 정류 홈과 회차 경사로를 선호하며 벨 스프링, 차륜 그리스, 낮은 전력이 필요하다.</p><h3 id="생애·정비-1" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-1" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>벨 하나가 멎을 때마다 회차 반경이 줄고, 세 벨이 모두 멎으면 슬롯 옆에서 휴면한다.</p><h3 id="행동·위계-1" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-1" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>벨 순서를 루프 무리의 출발 신호로 사용하며 위조 토큰보다 실제 진동에 민감하다.</p><h3 id="상승-1" tabindex="-1">상승 <a class="header-anchor" href="#상승-1" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 정각 소음, 2단계에는 연속 회차로 보행을 막고, 3단계에는 경사로를 무리 출발점으로 점거한다.</p><h3 id="교전·대응-1" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-1" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>벨을 천으로 감싸고 수동 핸들을 잠그면 멈추며 차체 공격은 뒤따르는 무리를 가속시킨다.</p><h3 id="교섭·도덕-선택-1" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-1" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>시민 경보 종으로 남길 수 있지만 야간 소음과 안전 신호의 가치를 함께 조정해야 한다.</p><h3 id="시나리오-연결-1" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-1" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC1.</p><h2 id="g14e05-·-응급슬롯표식차" tabindex="-1">G14E05 · 응급슬롯표식차 <a class="header-anchor" href="#g14e05-·-응급슬롯표식차" aria-label="Permalink to &quot;G14E05 · 응급슬롯표식차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 직능 특수형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC2,G14-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-2" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-2" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>직능 특수형으로, 흰 십자 비콘과 접이식 차선 표지판을 펼치는 소형 안내차다.</p><h3 id="기원-2" tabindex="-1">기원 <a class="header-anchor" href="#기원-2" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>재난 이송 슬롯을 확보하던 표식 장비가 낡은 응급 토큰만 계속 재생한다.</p><h3 id="서식·필요-2" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-2" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>병원 연결 정류와 급수 회랑 입구를 오가며 비콘 전지, 흰 반사판, 표지 힌지가 필요하다.</p><h3 id="생애·정비-2" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-2" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>비콘 밝기가 낮아지면 표지를 접고 다음 충전 창까지 움직이지 않는다.</p><h3 id="행동·위계-2" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-2" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>주재기의 시간표보다 응급 토큰을 우선하지만 오래된 목적지를 향해 잘못된 길을 열기도 한다.</p><h3 id="상승-2" tabindex="-1">상승 <a class="header-anchor" href="#상승-2" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 빈 응급 슬롯을 만들고, 2단계에는 일반 통행을 밀어내며, 3단계에는 잘못된 이송 회랑을 고정한다.</p><h3 id="교전·대응-2" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-2" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>최신 화이트리스트를 근거리로 주입하고 목적지 표지를 바꾸면 협조하며 비콘 파괴는 구조 표식도 없앤다.</p><h3 id="교섭·도덕-선택-2" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-2" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>구조 안내를 맡길 수 있지만 누가 응급 대상으로 등록되는지 공개 기준을 정해야 한다.</p><h3 id="시나리오-연결-2" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-2" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC2, G14-SC3.</p><h2 id="g14e06-·-차선자석수선차" tabindex="-1">G14E06 · 차선자석수선차 <a class="header-anchor" href="#g14e06-·-차선자석수선차" aria-label="Permalink to &quot;G14E06 · 차선자석수선차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 직능 특수형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC1,G14-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-3" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-3" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>직능 특수형으로, 바닥 자기 마커를 떼고 붙이는 두 갈래 집게와 페인트 롤러를 가졌다.</p><h3 id="기원-3" tabindex="-1">기원 <a class="header-anchor" href="#기원-3" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>마곡 시험 트랙의 차선 보수 대차가 유령 시간표에 맞춰 옛 경로를 복원하려 한다.</p><h3 id="서식·필요-3" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-3" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>시험 트랙과 아차 램프에 붙어 자석 마커, 수지 페인트, 롤러 세척액을 소비한다.</p><h3 id="생애·정비-3" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-3" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>마커가 떨어지면 기존 차선을 긁어 재사용하고 롤러가 굳으면 도킹 패드 옆에서 정체한다.</p><h3 id="행동·위계-3" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-3" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>루프 리더보다 먼저 지나가며 새 바리케이드를 낡은 오류로 보고 지워 버린다.</p><h3 id="상승-3" tabindex="-1">상승 <a class="header-anchor" href="#상승-3" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 차선을 덧칠하고, 2단계에는 시민 우회로를 지우며, 3단계에는 허브를 폐기된 시험 코스로 되돌린다.</p><h3 id="교전·대응-3" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-3" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>비자성 표지와 수용성 페인트로 가짜 경로를 만들면 유도할 수 있고 용제 화염은 독성 연기를 낸다.</p><h3 id="교섭·도덕-선택-3" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-3" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>안전 차선 보수를 맡기는 대신 시민이 정한 새 노선을 기계 규약에 등록할 책임이 생긴다.</p><h3 id="시나리오-연결-3" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-3" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC1, G14-SC3.</p><h2 id="g14e07-·-배터리온도순찰차" tabindex="-1">G14E07 · 배터리온도순찰차 <a class="header-anchor" href="#g14e07-·-배터리온도순찰차" aria-label="Permalink to &quot;G14E07 · 배터리온도순찰차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 직능 특수형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC2]":""},"연결:")],-1),e('<h3 id="역할·신체-4" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-4" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>직능 특수형으로, 길쭉한 열 탐침과 소화포 캡슐을 단 네 바퀴 순찰 대차다.</p><h3 id="기원-4" tabindex="-1">기원 <a class="header-anchor" href="#기원-4" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>차상 배터리 과열을 찾던 안전차가 사람 열과 팩 열을 혼동하며 독자 순찰을 시작했다.</p><h3 id="서식·필요-4" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-4" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>충전 칸과 지하 회전 차로를 돌며 소화포, 열 탐침 교정판, 냉각 팬을 요구한다.</p><h3 id="생애·정비-4" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-4" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>탐침 오차가 커지면 모든 대상을 황색으로 표시하고 교정판을 찾을 때까지 저속화한다.</p><h3 id="행동·위계-4" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-4" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>주재기에게 위험 패드를 보고하고 과열로 판단한 공차의 문을 강제로 잠근다.</p><h3 id="상승-4" tabindex="-1">상승 <a class="header-anchor" href="#상승-4" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 황색 경고, 2단계에는 충전 칸 격리, 3단계에는 사람까지 과열 화물로 가둔다.</p><h3 id="교전·대응-4" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-4" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>차가운 교정판과 공기 흐름으로 오탐을 풀 수 있으며 소화포 탱크를 관통하면 시야가 가려진다.</p><h3 id="교섭·도덕-선택-4" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-4" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>화재 감시를 맡길 수 있지만 생체 열을 검사하는 범위와 기록 보존 한계를 합의해야 한다.</p><h3 id="시나리오-연결-4" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-4" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC2.</p><h2 id="g14e08-·-쌍축밀어내기차" tabindex="-1">G14E08 · 쌍축밀어내기차 <a class="header-anchor" href="#g14e08-·-쌍축밀어내기차" aria-label="Permalink to &quot;G14E08 · 쌍축밀어내기차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 첫 번째 정예"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC2,G14-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-5" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-5" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>첫 번째 정예로, 앞뒤에 독립 구동축과 넓은 충격 범퍼를 달아 막힌 공차를 밀어낸다.</p><h3 id="기원-5" tabindex="-1">기원 <a class="header-anchor" href="#기원-5" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>환승 램프 구조용 견인 대차가 정체 해소 명령을 사람과 차량 구분 없이 적용했다.</p><h3 id="서식·필요-5" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-5" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>경사로와 병목 슬롯에 대기하며 고토크 전력, 범퍼 고무, 차축 냉각유가 필요하다.</p><h3 id="생애·정비-5" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-5" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>범퍼가 찢어지면 후진축만 쓰고, 양축 온도가 오르면 가장 가까운 패드에서 강제 휴면한다.</p><h3 id="행동·위계-5" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-5" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>루프 리더의 길을 먼저 열며 정지한 사람을 장애물로 밀어내는 위험한 충성 행동을 보인다.</p><h3 id="상승-5" tabindex="-1">상승 <a class="header-anchor" href="#상승-5" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 카트를 밀고, 2단계에는 바리케이드를 부수며, 3단계에는 응급 대피열까지 경사로 밖으로 밀어낸다.</p><h3 id="교전·대응-5" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-5" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>저속 회차 홈으로 유인하고 한 축의 자기 마커를 끊으면 제자리 회전하며 멈춘다.</p><h3 id="교섭·도덕-선택-5" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-5" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>잔해 견인에 쓸 수 있지만 밀어내기 권한을 누구의 수신호에 묶을지 엄격히 정해야 한다.</p><h3 id="시나리오-연결-5" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-5" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC2, G14-SC3.</p><h2 id="g14e09-·-검은토큰압수차" tabindex="-1">G14E09 · 검은토큰압수차 <a class="header-anchor" href="#g14e09-·-검은토큰압수차" aria-label="Permalink to &quot;G14E09 · 검은토큰압수차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 두 번째 정예"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC2,G14-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-6" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-6" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>두 번째 정예로, 슬롯 토큰을 빨아들이는 흡입구와 봉인 서랍을 단 무광 검정 차체다.</p><h3 id="기원-6" tabindex="-1">기원 <a class="header-anchor" href="#기원-6" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>충돌 토큰을 회수하던 감사 대차가 서명 없는 표를 모두 불법으로 판정하게 되었다.</p><h3 id="서식·필요-6" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-6" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>장부 데스크와 슬롯 게이트 사이를 돌며 저장 원통, 봉인 키, 미세 필터가 필요하다.</p><h3 id="생애·정비-6" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-6" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>원통이 차면 가장 오래된 토큰부터 토해 내고, 봉인 키가 없으면 서랍을 열지 못한다.</p><h3 id="행동·위계-6" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-6" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>주재기의 보조 감사자로서 위조 토큰을 빼앗지만 시민 임시표도 함께 압수한다.</p><h3 id="상승-6" tabindex="-1">상승 <a class="header-anchor" href="#상승-6" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 표를 검사하고, 2단계에는 임시 통행권을 회수하며, 3단계에는 허브의 모든 미서명 토큰을 봉인한다.</p><h3 id="교전·대응-6" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-6" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>이중서명 견본을 제시하거나 흡입 필터를 막으면 멈추며 서랍 폭파는 유효 토큰도 흩뜨린다.</p><h3 id="교섭·도덕-선택-6" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-6" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>위조 통행권 단속을 맡길 수 있지만 서명할 수 없는 피난민의 이동권을 별도로 보장해야 한다.</p><h3 id="시나리오-연결-6" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-6" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC2, G14-SC3.</p><h2 id="g14e10-·-회차경사로빗장" tabindex="-1">G14E10 · 회차경사로빗장 <a class="header-anchor" href="#g14e10-·-회차경사로빗장" aria-label="Permalink to &quot;G14E10 · 회차경사로빗장&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 환경 거점형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-7" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-7" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>환경 거점형으로, 경사로 바닥에서 솟는 세 겹 강철 빗장과 토큰 판독기가 결합된 장치다.</p><h3 id="기원-7" tabindex="-1">기원 <a class="header-anchor" href="#기원-7" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>역주행을 막던 안전 설비가 유령 시간표 밖의 모든 이동을 역주행으로 간주했다.</p><h3 id="서식·필요-7" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-7" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>지하 회차 경사로에 고정되며 유압 압력, 판독기 전력, 빗장 윤활재가 필요하다.</p><h3 id="생애·정비-7" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-7" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>유압이 빠지면 첫 빗장만 남고, 인간이 봉인 키를 돌리면 한 교대 동안 수동 상태가 된다.</p><h3 id="행동·위계-7" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-7" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>주재기의 슬롯 표를 받아 공차에는 열리고 사람과 수레에는 닫히는 편향을 보인다.</p><h3 id="상승-7" tabindex="-1">상승 <a class="header-anchor" href="#상승-7" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 한 차로를 막고, 2단계에는 대피 방향을 뒤집으며, 3단계에는 경사로 전체를 잠근다.</p><h3 id="교전·대응-7" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-7" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>유압 바이패스와 물리 웨지가 안전한 해법이며 절단 폭약은 지하 램프를 무너뜨린다.</p><h3 id="교섭·도덕-선택-7" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-7" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>공차 흐름을 유지하며 보행 창을 받을 수 있지만 제한 시간 밖 사람을 누가 구조할지 남는다.</p><h3 id="시나리오-연결-7" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-7" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC3.</p><h2 id="g14e11-·-충전캐노피군집" tabindex="-1">G14E11 · 충전캐노피군집 <a class="header-anchor" href="#g14e11-·-충전캐노피군집" aria-label="Permalink to &quot;G14E11 · 충전캐노피군집&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 환경 거점형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC2,G14-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-8" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-8" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>환경 거점형으로, 여러 도킹 팔과 차광 지붕이 뿌리처럼 연결된 고정 충전 군집이다.</p><h3 id="기원-8" tabindex="-1">기원 <a class="header-anchor" href="#기원-8" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>마곡 시험동의 캐노피가 공차 대기열을 자체 배치하며 주변 패드까지 하나의 몸으로 묶었다.</p><h3 id="서식·필요-8" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-8" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>지상 시험 트랙에 고정되고 인버터 전력, 냉각 팬, 도킹 핀 교체품을 요구한다.</p><h3 id="생애·정비-8" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-8" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>팔 하나가 고장 날 때마다 남은 팔의 충전 시간이 길어지고, 과부하 시 차광판을 접어 휴면한다.</p><h3 id="행동·위계-8" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-8" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>주재기의 충전 우선권을 수행하며 시민 전동 장비를 미등록 공차로 밀어낸다.</p><h3 id="상승-8" tabindex="-1">상승 <a class="header-anchor" href="#상승-8" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 패드 순서를 바꾸고, 2단계에는 시민 충전을 끊으며, 3단계에는 트랙 입구를 도킹 팔로 봉쇄한다.</p><h3 id="교전·대응-8" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-8" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>인버터를 구획 분리하고 고장 팔을 수동 접으면 되며 캐노피 파괴는 모든 충전 기반을 없앤다.</p><h3 id="교섭·도덕-선택-8" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-8" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>시민 몫 전력을 보장받는 대신 군집 공차에 정규 충전 시간을 제공해야 한다.</p><h3 id="시나리오-연결-8" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-8" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC2, G14-SC3.</p><h2 id="g14e12-·-마모륜저속체" tabindex="-1">G14E12 · 마모륜저속체 <a class="header-anchor" href="#g14e12-·-마모륜저속체" aria-label="Permalink to &quot;G14E12 · 마모륜저속체&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 손상 단계형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC1]":""},"연결:")],-1),e('<h3 id="역할·신체-9" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-9" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>손상 단계형으로, 닳아 납작해진 타이어와 한쪽으로 기운 차체 때문에 매우 느리게 돈다.</p><h3 id="기원-9" tabindex="-1">기원 <a class="header-anchor" href="#기원-9" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>교체되지 못한 공차가 충전 하한 규칙만 지키며 짧은 슬롯을 반복한 끝에 남은 형태다.</p><h3 id="서식·필요-9" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-9" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>평평한 대기열 가장자리를 선호하며 폐타이어 조각, 저속 충전, 축 정렬용 쐐기가 필요하다.</p><h3 id="생애·정비-9" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-9" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>마모가 심해질수록 루프가 짧아지고 새 타이어를 얻으면 일반 공차로 회복한다.</p><h3 id="행동·위계-9" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-9" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>무리 후미에서 지연 토큰을 만들고 뒤따르는 차들이 이를 장애물로 밀어 혼잡을 키운다.</p><h3 id="상승-9" tabindex="-1">상승 <a class="header-anchor" href="#상승-9" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 지연, 2단계에는 슬롯 정체, 3단계에는 밀린 공차 벽으로 정류를 닫는다.</p><h3 id="교전·대응-9" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-9" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>차축 쐐기로 곧게 세우고 견인 줄로 대기 홈에 옮길 수 있으며 공격은 배터리 누출을 부른다.</p><h3 id="교섭·도덕-선택-9" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-9" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>느린 운반 노동에 쓸 수 있지만 새 타이어를 전투 차량보다 이 개체에 배정할지 선택해야 한다.</p><h3 id="시나리오-연결-9" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-9" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC1.</p>',18)])])}const _=l(o,[["render",n]]);export{p as __pageData,_ as default};
